#!/usr/bin/env python3
"""Word count CLI that counts whitespace-separated words in a file."""

import sys


def count_words(filepath):
    """Count whitespace-separated words in a file."""
    try:
        with open(filepath, 'r') as f:
            content = f.read()
            words = content.split()
            return len(words)
    except FileNotFoundError:
        print(f"Error: File '{filepath}' not found.", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)


def main():
    """Main entry point for the CLI."""
    if len(sys.argv) != 2:
        print("Usage: python wc.py <filepath>", file=sys.stderr)
        sys.exit(1)

    filepath = sys.argv[1]
    word_count = count_words(filepath)
    print(word_count)


if __name__ == "__main__":
    main()

